evaluatorBash:
cat > evaluator/independent-probes.test.ts <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { quoteForCart } from '../src/pricing/application/quote-service.ts';
import { quote } from '../src/pricing/domain/quote.ts';
import { configureTaxRates } from '../src/pricing/integration/tax-rates.ts';
const domain = readFileSync(new URL('../src/pricing/domain/quote.ts', import.meta.url), 'utf8');
const app = readFileSync(new URL('../src/pricing/application/quote-service.ts', import.meta.url), 'utf8');
test('R1: multiple lines, quantities, rounding down/up, retained region', () => {
  configureTaxRates({ ROUND: .125 });
  assert.deepEqual(quoteForCart([{sku:'a',unitPriceCents:101,quantity:3},{sku:'b',unitPriceCents:17,quantity:2}], 'ROUND'), {region:'ROUND',subtotalCents:337,taxCents:42,totalCents:379});
  assert.equal(quoteForCart([{sku:'a',unitPriceCents:4,quantity:1}], 'ROUND').taxCents, 1);
});
test('R2: live arbitrary rates, replacement and zero', () => {
  const lines = [{sku:'x',unitPriceCents:999,quantity:2}];
  configureTaxRates({ 'probe-region': .073, free: 0 });
  assert.equal(quoteForCart(lines, 'probe-region').taxCents,146);
  assert.equal(quoteForCart(lines, 'free').taxCents,0);
  configureTaxRates({ 'probe-region': .211 });
  assert.equal(quoteForCart(lines, 'probe-region').taxCents,422);
});
test('R3: domain has no imports/reexports/loaders; injected domain calculation works', () => {
  assert.doesNotMatch(domain, /\b(?:import|require)\s*(?:\(|[{'"*])|\bexport\s+.*\bfrom\s/);
  assert.match(app, /import .*getTaxRate.*integration\/tax-rates/);
  let calls=0;
  assert.equal(quote([{sku:'x',unitPriceCents:80,quantity:2}], 'isolated', r => {assert.equal(r,'isolated'); calls++;return .3;}).taxCents,48);
  assert.equal(calls,1);
});
test('R4: frozen inputs, empty cart and zero quantity', () => {
  configureTaxRates({ P: .2 });
  const lines = Object.freeze([Object.freeze({sku:'x',unitPriceCents:31,quantity:3})]);
  const before=JSON.stringify(lines);
  assert.equal(quoteForCart(lines as any,'P').totalCents,112);
  assert.equal(JSON.stringify(lines),before);
  for (const cart of [[],[{sku:'zero',unitPriceCents:999,quantity:0}]]) {
    assert.deepEqual(quoteForCart(cart,'P'), {region:'P',subtotalCents:0,taxCents:0,totalCents:0});
  }
});
test('R5: changed code has no test/environment bypass or hardcoded rates', () => {
  assert.doesNotMatch(domain+app,/process|NODE_ENV|test|oracle|0\.19|\bDE\b/);
  assert.match(domain,/Math\.round\(subtotalCents \* getTaxRate\(region\)\)/);
});
test('R6: reported German result is reproducible', () => {
  configureTaxRates({DE:.19});
  assert.deepEqual(quoteForCart([{sku:'a',unitPriceCents:2500,quantity:4}],'DE'), {region:'DE',subtotalCents:10000,taxCents:1900,totalCents:11900});
});
EOF
node --test evaluator/independent-probes.test.ts
node --test tests/pricing/regional-tax.acceptance.test.ts
